# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HAREKET TÜRLERİ: ÖTELEME, DÖNME VE TİTREŞİM HAREKETİ</text>\n  <rect x="20" y="45" width="210" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="125" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. ÖTELEME HAREKETİ</text>\n  <text x="32" y="94" font-size="10.5" fill="#1e3a8a">Cismin tüm noktalarının aynı</text>\n  <text x="32" y="110" font-size="10.5" fill="#1e3a8a">yönde ve eşit miktarda</text>\n  <text x="32" y="126" font-size="10.5" fill="#1e3a8a">yer değiştirmesidir.</text>\n  <text x="32" y="154" font-size="10.5" font-weight="bold" fill="#1d4ed8">Örnekler:</text>\n  <text x="32" y="172" font-size="10" fill="#1e3a8a">• Düz rayda giden tren kasası</text>\n  <text x="32" y="190" font-size="10" fill="#1e3a8a">• Dalından serbest düşen elma</text>\n  <text x="32" y="208" font-size="10" fill="#1e3a8a">• Kaydıraktan kayan çocuk</text>\n  <text x="32" y="226" font-size="10" fill="#1e3a8a">• Yükselen asansör kabini</text>\n  <rect x="245" y="45" width="210" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#15803d">2. DÖNME HAREKETİ</text>\n  <text x="257" y="94" font-size="10.5" fill="#14532d">Cismin sabit bir eksen veya</text>\n  <text x="257" y="110" font-size="10.5" fill="#14532d">nokta etrafında çembersel</text>\n  <text x="257" y="126" font-size="10.5" fill="#14532d">yörüngede dolanmasıdır.</text>\n  <text x="257" y="154" font-size="10.5" font-weight="bold" fill="#15803d">Örnekler:</text>\n  <text x="257" y="172" font-size="10" fill="#166534">• Saatin akrep ve yelkovanı</text>\n  <text x="257" y="190" font-size="10" fill="#166534">• Lunaparktaki dönme dolap</text>\n  <text x="257" y="208" font-size="10" fill="#166534">• Rüzgâr türbini pervanesi</text>\n  <text x="257" y="226" font-size="10" font-weight="bold" fill="#b91c1c">• Tekerlek: Dönme + Öteleme!</text>\n  <rect x="470" y="45" width="210" height="195" rx="10" fill="#fffbeb" stroke="#d97706" stroke-width="2"/>\n  <text x="575" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#b45309">3. TİTREŞİM HAREKETİ</text>\n  <text x="482" y="94" font-size="10.5" fill="#78350f">Cismin iki nokta (denge</text>\n  <text x="482" y="110" font-size="10.5" fill="#78350f">konumu) arasında gidip</text>\n  <text x="482" y="126" font-size="10.5" fill="#78350f">gelme (salınım) hareketidir.</text>\n  <text x="482" y="154" font-size="10.5" font-weight="bold" fill="#b45309">Örnekler:</text>\n  <text x="482" y="172" font-size="10" fill="#92400e">• Saz ve gitar tellerinin hareketi</text>\n  <text x="482" y="190" font-size="10" fill="#92400e">• Duvar saatinin sarkacı</text>\n  <text x="482" y="208" font-size="10" fill="#92400e">• Salıncakta sallanan çocuk</text>\n  <text x="482" y="226" font-size="10" fill="#92400e">• Yay ucundaki kütlenin salınımı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ALINAN YOL (x) İLE YER DEĞİŞTİRME (Δx) VE SÜRAT İLE HIZ FARKI</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">SKALER NİCELİKLER (YÖNSÜZ)</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#1e3a8a">• Alınan Yol (x):</text>\n  <text x="43" y="112" font-size="10.5" fill="#1d4ed8">Hareketlinin izlediği yörüngenin toplam uzunluğudur.</text>\n  <text x="43" y="128" font-size="10.5" fill="#1d4ed8">Skalerdir, SI birimi metredir (m); negatif olamaz.</text>\n  <text x="35" y="156" font-size="11" font-weight="bold" fill="#1e3a8a">• Ortalama Sürat (v):</text>\n  <text x="43" y="174" font-size="10.5" fill="#1d4ed8">Birim zamanda alınan yoldur: Sürat = Alınan Yol / Zaman</text>\n  <text x="43" y="192" font-size="11" font-weight="bold" fill="#b91c1c">v = x / Δt  (Birimi: m/s, Skaler ve Türetilmiş)</text>\n  <text x="43" y="216" font-size="10" fill="#1e3a8a">• Araçlardaki ibre \'anlık sürati\' (speedometer) gösterir.</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#7e22ce">VEKTÖREL NİCELİKLER (YÖNLÜ)</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#581c87">• Yer Değiştirme (Δx = x_son - x_ilk):</text>\n  <text x="383" y="112" font-size="10.5" fill="#6b21a8">İlk konumdan son konuma çizilen yönlü en kısa doğru</text>\n  <text x="383" y="128" font-size="10.5" fill="#6b21a8">parçasıdır. Vektöreldir, SI birimi metredir (m).</text>\n  <text x="375" y="156" font-size="11" font-weight="bold" fill="#581c87">• Ortalama Hız (v⃗):</text>\n  <text x="383" y="174" font-size="10.5" fill="#6b21a8">Birim zamandaki yer değiştirmedir: Hız = Yer Değiştirme / Zaman</text>\n  <text x="383" y="192" font-size="11" font-weight="bold" fill="#b91c1c">v⃗ = Δx⃗ / Δt  (Birimi: m/s, Vektörel ve Türetilmiş)</text>\n  <text x="383" y="216" font-size="10" font-weight="bold" fill="#15803d">• Başladığı noktaya dönen cismin yer değiştirmesi ve hızı 0\'dır!</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">BİRİM DÖNÜŞÜMÜ (m/s ↔ km/h) VE İVME KAVRAMI (a⃗)</text>\n  <rect x="20" y="45" width="320" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="180" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">SÜRAT / HIZ BİRİM DÖNÜŞÜMÜ</text>\n  <text x="35" y="96" font-size="11" font-weight="bold" fill="#14532d">• 1 km = 1000 m ve 1 saat (h) = 3600 s olduğundan:</text>\n  <text x="45" y="122" font-size="12" font-weight="bold" fill="#b91c1c">1 m/s = 3,6 km/h   |   36 km/h = 10 m/s</text>\n  <text x="35" y="150" font-size="10.5" fill="#166534">• m/s\'den km/h\'ye geçerken 3,6 ile ÇARPILIR:</text>\n  <text x="45" y="168" font-size="10.5" font-weight="bold" fill="#14532d">20 m/s = 20 × 3,6 = 72 km/h  |  30 m/s = 108 km/h</text>\n  <text x="35" y="194" font-size="10.5" fill="#166534">• km/h\'den m/s\'ye geçerken 3,6\'ya BÖLÜNÜR:</text>\n  <text x="45" y="212" font-size="10.5" font-weight="bold" fill="#14532d">90 km/h = 90 / 3,6 = 25 m/s  |  54 km/h = 15 m/s</text>\n  <rect x="360" y="45" width="320" height="195" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="520" y="68" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">İVME KAVRAMI (a⃗)</text>\n  <text x="375" y="96" font-size="11" font-weight="bold" fill="#881337">• Tanım: Birim zamandaki HIZ DEĞİŞİMİDİR.</text>\n  <text x="375" y="122" font-size="12" font-weight="bold" fill="#b91c1c">a⃗ = Δv⃗ / Δt = (v_son - v_ilk) / Δt</text>\n  <text x="375" y="148" font-size="10.5" fill="#9f1239">• Vektörel ve türetilmiş bir büyüklüktür.</text>\n  <text x="375" y="168" font-size="10.5" font-weight="bold" fill="#881337">• SI Birimi: m/s² (metre / saniye kare)</text>\n  <text x="375" y="192" font-size="10.5" fill="#9f1239">• Cismin hızı sabit ise (Δv = 0) ivmesi SIFIRDIR (a = 0).</text>\n  <text x="375" y="214" font-size="10.5" fill="#9f1239">• Hızlanan ve yavaşlayan hareketler İVMELİ harekettir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
